import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"震为雷","description":"周易折中 - 震为雷","frontmatter":{"title":"震为雷","description":"周易折中 - 震为雷"},"headers":[],"relativePath":"zh/classics/zhezhong/057.md","filePath":"zh/classics/zhezhong/057.md"}'),h={name:"zh/classics/zhezhong/057.md"};function p(n,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="震为雷" tabindex="-1">震为雷 <a class="header-anchor" href="#震为雷" aria-label="Permalink to “震为雷”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>〈震〉序卦主器者莫若长子，故受之以《震》。《鼎》者，器也。《震》为长男，故取主器之义而继《鼎》之后。长子传国家继位号者也，故为主器之主。序卦取其一义之大者为相继之义。《震》之为卦，一阳生于二阴之下，动而上者也，故为《震》。震动也。不曰动者，《震》有动而奋发、震惊之义。乾坤之交，一索而成《震》，生物之长也，故为长男。其象则为雷，其义则为动。雷有震奋之象，动为惊惧之义。</p><p>震：亨。震来虩虩，笑言哑哑。震惊百里，不丧匕鬯。</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>震动也，一阳始生于二阴之下，震而动也。其象为雷，其属为长子。震有亨道，震来当震之来时也，虩虩恐惧惊顾之貌。震惊百里，以雷言。匕所以举鼎实，鬯以秬黍酒和郁金所以灌地降神者也。不丧匕鬯，以长子言也。此卦之占为能恐惧则致福，而不失其所主之重。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>阳生于下而上进，有亨之义。又震为动，为恐惧，为有主。震而奋发，动而进，惧而修，有主而保大，皆可以致亨。故震则有亨。当震动之来，则恐惧不敢自宁，旋顾周虑，虩虩然也。虩虩，顾虑不安之貌。蝇虎谓之虩者，以其周环顾虑不自宁也。处震如是，则能保其安裕，故笑言哑哑。哑哑，言笑和适之貌。震惊百里，不丧匕鬯，言震动之大而处之之道。动之大者莫若雷，震为雷，故以雷言。雷之震动，惊及百里之远人，无不惧而自失。雷声所及百里也，唯宗庙祭祀执匕鬯者，则不致于丧失。人之致其诚敬，莫如祭祀。匕以载鼎实升之于爼，鬯以灌地而降神。方其酌祼以求神，荐牲而祈享，尽其诚敬之心，则虽雷震之威不能使之惧而失守。故临大震惧能安而不自失者，唯诚敬而已。此处震之道也。卦才无取，故但言处震之道。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>干氏宝曰 ：祭礼荐陈甚多，而经独言不丧匕鬯者，匕牲体荐，鬯酒人君所自亲也。</p></li><li><p>胡氏瑗曰 ：百里雷声之所及也。匕者，宗庙之器，以棘木为之，似毕而无两岐，所以举鼎之实而升于爼也。鬯者，以郁金草和酒而有芬芳调鬯之气。</p></li><li><p>胡氏炳文曰 ：震惊百里，以震为雷取象；不丧匕鬯，以长子主器取象。震亨谓震有亨之道，又自以震来虩虩释震字，以笑言哑哑以下释亨字。</p></li><li><p>蔡氏清曰 ：震来当震之来时也，以心言，谓事之可惧而吾惧之也。其震惧之也，虩虩然。非震来而后虩虩也，虩虩所以状其震来也。或曰“来者自外来也”，故爻云“震来厉”，又云“震不于其躬，于其邻”。此说非惟昧卦辞“震来”之义，亦失卦名“震”字之义矣。盖震之来，来犹至也，固亦有其事。然震之至，则在我也。六二“震来厉”，谓当震之来而危厉，此震来正与卦辞旨同。至于“震不于其躬”，本义分明有“恐惧脩省”字，其与卦辞同益明矣。凡有所事者，皆当惧。惧便是震来也。君子之心常存敬畏，执事便敬，所以致福而不失其所主之重。又曰：震来虩虩以心言，震惊百里以事言，不丧匕鬯不惧也。不惧由于能惧。</p></li><li><p>余氏本曰 ：震惊百里只是足“笑言哑哑”一句意，大意谓人平时若能恐惧，则可以致福，虽卒然祸变之来，亦无可畏也。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>震来之义，蔡氏得之矣。</p><p>象曰：洊雷震，君子以恐惧脩省</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>洊，重袭也。上下皆震，故为洊雷。雷重仍，则威益盛。君子观洊雷威震之象，以恐惧自脩饬，循省也。君子畏天之威，则脩正其身，思省其过咎而改之。不唯雷震，凡遇惊惧之事，皆当如是。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>项氏安世曰 ：恐惧脩省，所谓洊也。人能恐惧，则既震矣；又脩省焉，洊在其中矣。</p></li><li><p>胡氏炳文曰 ：恐惧作于心，脩省见于事。脩，克治之功；省，审察之力。</p></li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>恐惧脩省者，君子之洊雷也。非遇雷震而恐惧也，须从项氏之说理解。</p><p>彖曰：震，亨</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>震有亨道，不待言也。</p><p>震来虩虩，恐致福也；笑言哑哑，后有则也</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>恐致福，恐惧以致福也；则，法也。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>震自有亨之义，非由卦才。震来而能恐惧，自修自慎，则可反致福吉。笑言哑哑，言自若也。由能恐惧而后自处有法则也，有则则安而不惧矣，处震之道也。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>董氏曰 ：致福云者，见君子常以危为安也。有则云者，见君子不以忽忘敬也。</p></li><li><p>李氏过曰 ：有则，谓君子所履出处语默皆有常则，不以恐惧而变也。</p></li></ul><p>震惊百里，惊远而惧迩也；出可以守宗庙社稷，以为祭主也</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>程子以为“迩也”下，脱“不丧匕鬯”四字，今从之。“出”，谓继世而主祭也。或云，出即鬯字之误。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>雷之震及于百里，远者惊，迩者惧，言其威远大也。彖文脱“不丧匕鬯”一句，卦辞云“不丧匕鬯”，本谓诚敬之至，威惧不能使之自失。彖以长子宜如是，因承上文用长子之义通解之，谓其诚敬能不丧匕鬯，则君出而可以守宗庙社稷为祭主也。长子如是，而后可以守世祀承国家也。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱子语类云 ：震便自是亨，震来虩虩是恐惧顾虑，而后便笑言哑哑；震惊百里便也不丧匕鬯。文王语已是解震亨了，孔子又自说长子事。</p></li><li><p>丘氏富国曰 ：惊者，卒然遇之而动乎外；惧者，惕然畏之而变于中。</p></li><li><p>张氏清子曰 ：出者，即说卦“帝出乎震”之谓；主者，即序卦“主器莫若长子”之谓。若舜之“烈风雷雨弗迷”，可以出而嗣位矣。</p></li><li><p>蔡氏清曰 ：惧深于惊，远近之别也。</p></li><li><p>杨氏启新曰 ：干者自强而已矣，而曰惕；震者动而已矣，而曰惧。惕之为强也，见惕之非惴慑也；惧之为动也，见惧之非惊恐也。</p></li></ul><p>初九：震来虩虩，后笑言哑哑，吉</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>成震之主，处震之初，故其占如此。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>初九，成震之主，致震者也。在卦之下，处震之初，知震之来当震之始。若能以为恐惧而周旋顾虑，虩虩然不敢宁止，则终必保其安吉。故后笑言哑哑也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>石氏介曰 ：初九有阳明之德，居震之始，是能先戒惧者，故繇彖所言此爻当之。</p></li><li><p>胡氏炳文曰 ：初九在内卦之内，震之主也，故辞与卦同。盖震之用在下，而重震之初又最下者，所以为震之主也。</p></li></ul><p>象曰：震来虩虩，恐致福也；笑言哑哑，后有则也</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>震来而能恐惧周顾，则无患矣。是能因恐惧而反致福也。因恐惧而自脩省，不敢违于法度，是由震而后有法则，故能保其安吉而笑言哑哑也。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li>范氏仲淹曰 ：君子之惧于心也，思虑必愼，其始则百志弗违于道；惧于身也，进退不履于危，则百行弗罹于祸。故初九震来而致福，愼于始也。</li></ul><p>六二：震来厉，亿丧贝，跻于九陵，勿逐，七日得</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>六二乘初九之刚，故当震之来而危厉也。亿字未详，又当丧其货贝而升于九陵之上。然柔顺中正，足以自守，故不求而自获也。此爻占具象中，但九陵七日之象则未详耳。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>六二居中得正，善处震者也。而乘初九之刚，九震之主，震刚动而上奋，孰能御之？厉猛也，危也。彼来既猛，则已处危矣。亿度也，具所有之资也。跻，升也。九陵，陵之高也。逐，往追也。以震来之厉，度不能当而必丧其所有，则升至高以避之也。九言其重，冈陵之重高之至也，九重之多也，如九天九地也。勿逐，七日得。二之所贵者中正也。遇震惧之来，虽量势巽避，当守其中正，无自失也。亿之必丧也，故远避以自守，过则复其常矣。是勿逐而自得也。逐即物也，以已即物失其守矣，故戒勿逐。避远自守，处震之大方也。如二者当危惧而善处者也。卦位有六七，乃更始事既终，时既易也。不失其守，虽一时不能御其来，然时过事已，则复其常，故云七日得。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>郑氏汝谐曰 ：亿度也，度宝货之可丧而丧之，不惮九陵之险而升之，避害以自全，静退以观变，事定则必得其所谓安利也。</p></li><li><p>杨氏简曰 ：六二乘初九之刚，不可安处，故亿丧具往而跻于九陵。虽今未得，至于历七日，则时当得矣。勿用逐也。避难曲折有如此者，昔太王既不可御狄，不可安处，去而邑于岐山之下，而他日兴周焉，此象也。</p></li><li><p>蒋氏悌生曰 ：亿度也，事未至未著而先谋度之谓亿。</p></li><li><p>杨氏启新曰 ：丧自丧之也，跻于九陵，飘然远举之意。人之所以常蹈祸者，利耳。远利而自处于高，岂惟无厉，所丧者可以不久而获矣。</p></li></ul><p>象曰：震来厉，乘刚也</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>当震而乘刚，是以彼厉而已危。震刚之来，其可御乎？</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏炳文曰 ：屯六二、豫六五、噬嗑六二、困六三、震六二皆言乘刚，惟困六三乘坎之中爻，其馀皆乘震之初也。</li></ul><p>六三：震苏苏，震行无眚</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>苏苏，缓散自失之状。以阴居阳，当震时而居不正，是以如此。占者若因惧而能行，以去其不正，则可以无眚矣。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>苏苏，神气缓散自失之状。三以阴居阳，不正处。不正于平时且不能妄，况处震乎？故其震惧而苏苏然。若因震惧而能行去不正而就正，则可以无过眚（过也）。三行则至四正也，动以就正为善，故二“勿逐”则自得，三能行则无眚。以不正而处震，惧有眚可知。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>赵氏光大曰 ：当震时而惧益甚，精神涣散，故为震苏苏之象。然天下不患有忧惧之时，而患无脩省之功。若能因此惧心而行，则持身无妄动，应事有成规，又何眚之有？</p></li><li><p>杨氏启新曰 ：震而不行，徒震耳。行者改图也，此恐惧所以脩省也。</p></li></ul><p>象曰：震苏苏，位不当也</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>其恐惧自失，苏苏然。由其所处不当故也，不中不正，其能安乎？</p><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>震当虩虩，不当苏苏。六三当重震之闲，正奋厉以有为之时也，而以阴不中正处之，至于苏苏缓散，故曰位不当。</p><p>九四：震遂泥</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>以刚处柔，不中不正，陷于二阴之闲，不能自震也。遂者，无反之意；泥，滞溺也。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>九四居震动之时，不中不正，处柔失刚健之道，居四无中正之德，陷溺于重阴之闲，不能自震奋者也。故云“遂泥”，泥滞溺也。以不正之阳而上下重阴，安能免于泥乎？遂无反之意，处震惧则莫能守也，欲震动则莫能奋也。震道亡矣，岂复能光亨也？</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>项氏安世曰 ：初九以一阳动乎二阴之下，得震之本象，故其福与卦辞合。九四以一阳动乎四阴之中，则震变成坎，震而遂陷于泥也。</p></li><li><p>胡氏炳文曰 ：初与四皆震之所以为震者，然震之用在下，四溺于阴柔之中，故震之亨在初而不在四。</p></li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>卦爻“震”字虽以人心为主，然震之本象则雷也。凡雷乘阳气而动，然所乘之气不同，故邵子曰“水雷玄，火雷赫，土雷连，石雷霹”。盖雷声有动而不能发逹者，陷于阴气也。此爻阳动于四阴之中，故有“震遂泥”之象。在人则志气未能自遂，乃困心衡虑之时也。</p><p>象曰：震遂泥，未光也</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>阳者刚物，震者动义。以刚处动，本有光亨之道，乃失其刚正而陷于重阴，以致遂泥，岂能光也？云“未光”，见阳刚本能震也，以失德故泥耳。</p><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>四有刚德，非失德者。此言未光，盖志气未能自遂，行拂乱其所为耳，与噬嗑九四之未光同，皆谓所处者未能遂其所志，非兑上未光之比。</p><p>六五：震往来厉，亿无丧，有事</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>以六居五而处震时，无时而不危也。以其得中，故无所丧而能有事。占者不失其中，则虽危无丧矣。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>六五虽以阴居阳，不当位为不正，然以柔居刚，又得中，乃有中德者也。不失中则不违于正矣，所以中为贵也。诸卦二五虽不当位，多以中为美；三四虽当位，或以不中为过。中常重于正也，盖中则不违于正，正不必中也。天下之理莫善于中，于六二、六五可见。五之动，上往则柔不可居动之极，下来则犯刚，是往来皆危也。当君位，为动之主，随宜应变，在中而已。故当亿度无丧，失其所有之事而已。所有之事，谓中德。苟不失中，虽有危，不至于凶也。亿度，谓图虑求不失中也。五所以危，由非刚阳而无助，若以刚阳有助为动之主，则能亨矣。往来皆危时，则甚难，但期于不失中，则可自守。以柔主动，固不能致亨济也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>虞氏翻曰 ：可以守宗庙社稷，为祭主，故无丧有事也。</p></li><li><p>项氏安世曰 ：二居下震之上，故称“来”；五居重震之上，故称“往来”。亿度也，二五之厉即震之恐惧也，二五之亿即震之脩省也。</p></li><li><p>熊氏良辅曰 ：震往亦厉，来亦厉，皆以危惧待之，故能无丧有事。盖不失其所有也。此卦辞所谓“不丧匕鬯，能主器以君天下”者与。</p></li><li><p>俞氏琰曰 ：二曰“震来”，指初之来。以五视初，则初之始震为既往，四之洊震为复来。五盖震往而复来之时也。“有事”谓有事于宗庙社稷也。震之主爻在初，而“无丧有事”乃归之五，五乃震之君也。案春秋凡祭祀皆曰“有事”，故此“有事”谓祭也。二五之震同，其有中德而能亿度于事理者亦同。然二丧具而五无丧者，二居下位，所有者具耳；五居尊，所守者则宗庙社稷也，具可丧也，宗庙社稷可以失守乎？故二以丧贝为中，五以无丧有事为中。</p></li></ul><p>象曰：震往来厉，危行也；其事在中，大无丧也</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>往来皆厉，行则有危也。动皆有危，唯在无丧其事而已。其事谓中也，能不失其中，则可自守也。大无丧，以无丧为大也。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>张子曰 ：无丧有事，犹云不失其所有也。以其乘刚故危，以其在中故无丧。祸至与不至皆惧，则无丧有事。</p></li><li><p>郭氏雍曰 ：二以来厉而丧贝，则五之往来皆厉，宜其大有丧也。六五位虽不正，而用中焉，其事既不失中道，虽涉危行，可以大无丧矣。</p></li></ul><p>上六：震索索，视矍矍，征凶。震不于其躬，于其邻，无咎。婚媾有言。</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>以阴柔处震极，故为索索、矍矍之象。以是而行，其凶必矣。然能及其震未及身之时，恐惧脩省，则可以无咎，而亦不能免于婚媾之有言。戒占者当如是也。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>索索，消索不存之状，谓其志气如是。六以阴柔居震动之极，其惊惧之甚，志气殚索也。矍矍，不安定貌，志气索索则视瞻徊徨。以阴柔不中正之质而处震动之极，故征则凶也。震之及身乃于其躬也，不于其躬谓未及身也。邻者，近于身者也。能震惧于未及身之前，则不至于极矣，故得无咎。苟未至于极，尚有可改之道。震终当变柔，不固守，故有畏邻戒而能变之义。圣人于震终示人知惧能改之义为劝，深矣。婚媾，所亲也，谓同动者有言，有怨咎之言也。六居震之上，始为众动之首，今乃畏邻戒而不敢进，与诸处震者异矣，故婚媾有言也。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>郑氏汝谐曰 ：上以阴柔之资而居一卦之上，其中无所得，不能自安，故震索索而气不充，视矍矍而神不固。人之过于恐惧者固无足取，若能举动之际，睹事之未然而知戒，亦圣人之所许也。</p></li><li><p>赵氏光大曰 ：阴处震极，故当震之来，志气消沮，瞻视彷徨，惊惧之甚也。以是而行，其志先乱，凶也。所以然者，以不能图之于早也。若震未及身而方及邻之时，恐惧脩省，豫为之图，则自无索索、矍矍之咎矣。</p></li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>此“婚媾有言”与《夬》四“闻言不信”同，皆占戒之外反言以决之之辞也。琐琐姻娅，见识凡近，当祸患之未至，则相诱以晏安而已尔，安能为人深谋长虑而相与儆戒于未然乎？</p><p>象曰：震索索，中未得也；虽凶无咎，畏邻戒也</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>中，谓中心。</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>所以恐惧自失如此，以未得于中道也。谓过中也，使之得中，则不至于索索矣。极而复征，则凶也。若能见邻戒而知惧，变于未极之前，则无咎也。上六动之极，震极则有变义也。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>吴氏澄曰 ：畏邻戒，谓因邻之戒而知畏也</p></li><li><p>龚氏焕曰 ：中未得者，处震之极，志气消索，中无所主也。若能畏惧邻爻之戒，及时调整自己的行为，则可避免灾祸，达到无咎的境界。</p></li></ul>',114)])])}const m=e(h,[["render",p]]);export{b as __pageData,m as default};
